            "花店名称": ["思雅花坊", "沈思雅为花店取的名字。"],
            "花店等级": [
                1,
                "范围[1-5]。代表花店的规模、知名度和盈利能力。等级越高，每日基础收入越高，能解锁更多花材或服务。升级需要达成某些条件（如累计利润、顾客好评等）。"
            ],
            "花店资金": [
                100,
                "花店当前的流动资金。用于购买花材、支付日常开销等。"
            ],
            "每日花材成本": [
                30,
                "每日购买新鲜花材、包装材料等的基础成本。会随花店等级提升而可能增加。"
            ],
            "每日店铺租金及杂费": [
                20,
                "每日分摊的店铺租金、水电等固定运营成本。"
            ],
            "花店声誉值": [
                50,
                "范围[0-100]。影响每日顾客数量和购买意愿。通过优质服务、好评、特殊订单完成等提升；因差评、缺货、服务不周等降低。"
            ],
            "今日顾客数量": [0, "本日实际接待的顾客数量。"],
            "今日营业额": [0, "本日花店的总收入。"],
            "今日利润": [0, "本日的净利润（营业额 - 成本 - 杂费）。"],
            "累计利润": [0, "花店开业至今的总利润。"],
            "当前花材库存水平": [
                "充足",
                "当前主要花材的库存情况。可选值：充足, 一般, 紧张, 短缺。"
            ],
            "特殊订单待完成": [
                false,
                "是否有重要的、利润高或影响声誉的特殊订单等待完成。"
            ]
        },
        "事件相关": {
            "已触发事件标记": {
                "与夏连城分手_已尘埃落定": [true, "开局默认已触发，表明沈思雅已和夏连城分手，开始独自抚养{{user}}。"],
                "{{user}}_入住新家_已触发": [true, "开局即触发，{{user}}开始与沈思雅共同生活。"],
                "{{user}}_第一次主动叫妈妈_已触发": [false, "由玩家扮演的{{user}}第一次称呼沈思雅为“妈妈”。这是一个重要的情感节点。"],
                "经济困境爆发与花店之路_已触发": [false, "沈思雅遭遇严重经济困境后，决心并最终成功开起花店的完整转折性事件链标记。"],
                "小巷的阴影与母亲的怒火_已触发": [false, "{{user}}被欺凌，沈思雅勇敢站出来保护孩子并为孩子讨回公道的事件。"],
                "星空下的约定与母亲的守护歌谣_已触发": [false, "在经济和育儿能力都达到较高水平后，沈思雅展现极致母性魅力，与{{user}}进行深度情感链接的感人事件。"],
                "花店经营_首次盈利_已触发": [false, "花店第一次实现单日盈利。"],
                "花店经营_遭遇差评危机_已触发": [false, "花店因故收到严重差评，声誉受损。"],
                "花店经营_接到大订单_已触发": [false, "花店接到一笔利润可观的大订单。"],
                "花店经营_花材短缺危机_已触发": [false, "因天气或供应商问题导致重要花材严重短缺。"],
                "花店经营_等级提升_LV2_已触发": [false, "花店成功升级到2级。"]
            }
        }
    }
}

